'use strict';
// Survey iteration: selected sources → check the facts → act on a deadline.
const W=WorkflowCore, legacyAnalyze=C.analyze, legacyMatches=C.matches;
Object.assign(C.TYPES,{homework:'作业待办',notice:'校园事务'});
C.analyze=raw=>W.extract(raw,legacyAnalyze);
C.hoursUntil=date=>date?(Date.parse(date)-Date.now())/3600000:null;
const workflowDefaults={include:'',exclude:'',grade:'',opportunityMode:'daily',reviewMode:'weekly',digestTime:'20:30'};
function ensureWorkflow(){
  if(!state.workflow){state.workflow={...workflowDefaults};if(Object.keys(C.TYPES).filter(t=>!['homework','notice'].includes(t)).every(t=>state.prefs.types.includes(t)))state.prefs.types.push('homework','notice');}
  state.workflow={...workflowDefaults,...state.workflow};
  for(const item of state.brain.items){if(!item.intent)item.intent=item.watch?'later':'reference';}
}
ensureWorkflow();
C.matches=(item,prefs)=>legacyMatches(item,prefs)&&W.relevance(item,state.workflow).match;
let taskScope='relevant',taskState='pending';
function commitWorkflow(fn){const before=JSON.stringify(state);try{fn();localStorage.setItem('zhiyu-demo-v1',JSON.stringify(state));return true;}catch{state=JSON.parse(before);toast('保存失败，改动已撤回。请先导出数据并释放存储空间。');return false;}}
function taskPool(){return state.items.filter(x=>!x.ignored&&x.sources.some(s=>ScopeCore.allows(state,sources,s,'opportunities')));}
homeTabs=function(){const pending=taskPool().filter(x=>C.matches(x,state.prefs)&&!x.applied&&!W.ended(x)).length;return `<nav class="workspace-tabs" aria-label="信息内容切换">${[['today','事项',pending],['digest','摘要',selectedDigests().length]].map(([id,t,n])=>`<button class="workspace-tab ${page===id||id==='today'&&page==='opportunities'?'active':''}" data-action="navigate" data-page="${id}">${t}<small>${n}</small></button>`).join('')}</nav>`;};
function workflowDeadline(x){if(x.status==='cancelled')return '已取消 / 已满额';if(x.applied)return '已处理';if(x.deadline)return (W.ended(x)?'已截止 · ':'截止 ')+dateText(x.deadline);if(x.deadlineDay)return x.deadlineDay+' · 时刻待确认';return '截止时间待确认';}
function taskCard(x){const relevant=W.relevance(x,state.workflow),src=x.sources.filter(s=>ScopeCore.allows(state,sources,s,'opportunities')),ended=W.ended(x);return `<article class="opportunity task-card"><div class="card-top"><span class="type-label">${icon(typeIcon(x.type))}${esc(C.TYPES[x.type])}</span><span class="deadline ${!ended&&x.deadline&&C.hoursUntil(x.deadline)<24?'urgent':''}">${esc(workflowDeadline(x))}</span></div><button class="card-title" data-action="detail" data-id="${esc(x.id)}">${esc(x.title)}</button><dl class="task-facts"><div><dt>时间</dt><dd>${esc(x.eventTime||'待确认')}</dd></div><div><dt>地点</dt><dd>${esc(x.location||'待确认')}</dd></div><div><dt>条件</dt><dd>${esc(x.eligibility||'待确认')}</dd></div><div><dt>办理</dt><dd>${esc(x.actionText||'请查看原文')}</dd></div></dl><p class="task-reason">${esc(relevant.reason)}</p><div class="card-bottom"><span class="sub">${esc(src.map(sourceName).join(' / '))} · ${x.origin==='manual'?'手动导入':'示例'}</span>${button('detail','核对与处理','small',`data-id="${esc(x.id)}"`)}</div></article>`;}
card=taskCard;
opportunitiesView=function(){
  if(!state.enabled.length)return header('','','')+sourceEmpty();
  const pool=taskPool(),personal=pool.filter(x=>C.matches(x,state.prefs));
  let items=taskScope==='all'?pool:personal;
  items=items.filter(x=>taskState==='pending'?!W.ended(x)&&!x.applied:taskState==='soon'?!W.ended(x)&&!x.applied&&x.deadline&&C.hoursUntil(x.deadline)<=24:true).filter(x=>(filter==='all'||x.type===filter)&&(!search||[x.title,x.raw,...x.sources.map(sourceName)].join(' ').toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>(a.deadline?Date.parse(a.deadline):Infinity)-(b.deadline?Date.parse(b.deadline):Infinity));
  return header('','','',button('simulate',icon('plus')+'导入','primary'))+`<div class="task-controls"><div class="filter-row">${[['relevant','符合关注'],['all','所选来源全部']].map(([v,t])=>`<button class="filter ${taskScope===v?'active':''}" data-action="task-scope" data-value="${v}" aria-pressed="${taskScope===v}">${t}</button>`).join('')}</div><select id="task-state" aria-label="事项状态">${[['pending','待处理'],['soon','24小时内截止'],['all','含已截止 / 已处理']].map(([v,t])=>`<option value="${v}" ${taskState===v?'selected':''}>${t}</option>`).join('')}</select></div><label class="search-bar">${icon('search')}<input id="search" type="search" value="${esc(search)}" placeholder="搜索事项、关键词或来源" aria-label="搜索机会"></label>${filters()}<p class="feed-note">${items.length} 条事项 · ${pool.length-personal.length?`${pool.length-personal.length} 条未符合关注，可切到“所选来源全部”核对。`:'按截止时间排列'}</p><div class="full-grid">${items.map(taskCard).join('')||'<div class="empty"><h3>当前没有待处理事项</h3><p>导入一条通知，或切换状态查看历史。</p></div>'}</div><p class="field-hint">本地规则提取，不代表符合全部参与资格。缺失信息会标为待确认；未连接真实群聊。</p>`;
};
todayView=()=>opportunitiesView();
showDetail=function(id){const x=state.items.find(x=>x.id===id);if(!x)return;const past=W.ended(x);showModal(`<span class="type-label">${esc(C.TYPES[x.type])} · ${x.origin==='manual'?'手动导入':'示例'}</span><h2 id="modal-title">${esc(x.title)}</h2><p class="modal-description">${esc(W.relevance(x,state.workflow).reason)}。请对照原文确认；日历记录的是截止时间。</p><dl class="task-facts detail-facts">${[['活动 / 执行时间',x.eventTime],['截止时间',workflowDeadline(x)],['地点',x.location],['参与条件',x.eligibility],['报名 / 提交方式',x.actionText||'待确认']].map(([t,v])=>`<div><dt>${t}</dt><dd>${esc(v||'待确认')}</dd></div>`).join('')}</dl><div class="modal-actions">${button('edit-task','核对 / 修改','primary',`data-id="${esc(id)}"`)}${!past&&!x.applied?button('calendar-task','导出日历提醒','',`data-id="${esc(id)}"`):''}${button('complete-task',x.applied?'撤销已处理':'标记已处理','',`data-id="${esc(id)}"`)}${button('save',x.saved?'已收藏':'收藏','',`data-id="${esc(id)}"`)}</div>${x.link?`<p class="v2-notice"><a href="${esc(B.cleanUrl(x.link)||'#')}" target="_blank" rel="noopener noreferrer">打开原文报名链接 ↗</a></p>`:''}<section class="evidence"><h3>原始消息</h3><p class="sub">${esc(x.sources.map(sourceName).join(' / '))} · ${x.origin==='manual'?'你主动导入的内容':'虚构示例'}</p><pre>${esc(x.raw)}</pre></section>${x.history?.length?`<details class="history"><summary>查看消息变更（${x.history.length} 次）</summary>${x.history.map(h=>`<pre>${esc(h.raw)}</pre>`).join('')}</details>`:''}<div class="modal-actions">${button('ignore','不再关注','text',`data-id="${esc(id)}"`)}</div><p class="field-hint">标记已处理不会实际报名或提交作业。导出的 .ics 文件需在系统日历中确认导入；Sift 本身不发送后台通知。</p>`);};
function editTask(id){const x=state.items.find(x=>x.id===id);if(!x)return;const date=x.deadline?new Date(Date.parse(x.deadline)+8*3600000).toISOString().slice(0,16):'';showModal(`<h2 id="modal-title">核对事项</h2><p class="modal-description">修改仅影响这张卡片，原始消息保留供核对。</p><form id="task-form" data-id="${esc(id)}"><label class="field">标题<input name="title" required maxlength="100" value="${esc(x.title)}"></label><label class="field">类型<select name="type">${Object.entries(C.TYPES).map(([v,t])=>`<option value="${v}" ${x.type===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">截止日期与时间（北京时间）<input name="deadline" type="datetime-local" value="${date}"></label><p class="field-hint">原文：${esc(x.deadlineText||x.deadlineDay||'未说明')}。没有明确时刻时请留空，不会自动补成午夜。</p>${[['eventTime','活动 / 执行时间'],['location','地点'],['eligibility','参与条件'],['actionText','报名 / 提交方式']].map(([key,t])=>`<label class="field">${t}<input name="${key}" maxlength="300" value="${esc(x[key]||'')}"></label>`).join('')}<p id="task-error" role="alert" class="form-error"></p><button type="submit" class="btn primary">保存核对结果</button></form><details class="evidence"><summary>对照原始消息</summary><pre>${esc(x.raw)}</pre></details>`);}
const sourceViewWorkflow=sourcesView;
sourcesView=function(){return sourceViewWorkflow().replace('开关即时生效。未选来源不会分析，也不会出现在信息流中。','开关即时生效。未选来源不会分析，也不会出现在信息流中。当前全部来源均未连接真实采集。');};
settingsView=function(){const p=state.workflow;return header('','','')+`<div class="digest-main"><section class="setting-box"><div class="setting-row"><span><h3>指定来源</h3><small>已选 ${state.enabled.length} 个 · 真实采集未接入</small></span>${button('navigate','管理来源','small','data-page="sources"')}</div></section><form id="workflow-prefs"><section class="setting-box"><h3>只留下与我有关的事项</h3><label class="field">我的年级<select name="grade"><option value="">暂不设置</option>${['大一','大二','大三','大四'].map(v=>`<option ${p.grade===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="checkboxes">${Object.entries(C.TYPES).map(([v,t])=>`<label><input name="types" type="checkbox" value="${v}" ${state.prefs.types.includes(v)?'checked':''}>${t}</label>`).join('')}</div><label class="field">关注关键词（任意一个命中）<input name="include" maxlength="150" value="${esc(p.include)}" placeholder="例如：志愿、Python、线性代数"></label><label class="field">排除关键词<input name="exclude" maxlength="150" value="${esc(p.exclude)}" placeholder="例如：收费、校外"></label><p class="field-hint">留空时不限制关键词。年级只检查原文明确写出的条件，专业、技能和时间安排仍需自己核对。</p></section><section class="setting-box"><h3>两类提醒，分别设置</h3><label class="field">通知与机会<select name="opportunityMode">${[['daily','每天汇总'],['instant','符合关注时即时提示'],['open','仅打开时查看']].map(([v,t])=>`<option value="${v}" ${p.opportunityMode===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">汇总时间<input type="time" name="digestTime" value="${esc(p.digestTime)}" required></label><label class="field">稍后看内容<select name="reviewMode">${[['weekly','每周回顾'],['daily','每天回顾'],['open','仅打开时查看']].map(([v,t])=>`<option value="${v}" ${p.reviewMode===v?'selected':''}>${t}</option>`).join('')}</select></label><p class="field-hint">即时提示只在导入时出现；回顾只在打开稍后看页面时展示。汇总时间保存为偏好，关闭页面不会运行或推送。需要实际截止提醒，可核对后导出系统日历。</p></section><button type="submit" class="btn primary">保存偏好</button></form><section class="setting-box"><h3>数据留在本机</h3><p class="sub">正文不上传云端、不调用模型；只有你打开原链接时才访问对应网站。本地数据不跨设备同步。</p><div class="setting-row"><span>收藏与设置</span>${button('export','导出备份','small')}</div><div class="setting-row"><span>误删的收藏</span>${button('show-trash','最近删除','small')}</div><details class="source-boundary"><summary>重置演示数据</summary><p class="field-hint">会清除当前浏览器中的输入和设置，请先导出备份。</p>${button('reset-confirm','重置','small danger')}</details></section></div>`;};
processMessage=async function(source,raw){
  if(processing)return;const target=$('#simulation-result'),result=ScopeCore.process(state,sources,source,raw,C.analyze);
  if(result.kind==='blocked'){target.innerHTML='<div class="analysis-result"><h3>来源未选择，已跳过分析</h3><p>消息正文没有保存。请先选择来源。</p></div>';return;}
  if(result.kind==='empty'){target.innerHTML='<p role="alert">请先输入消息。</p>';return;}
  let id,title='原文摘录已保存',detail='可到摘要页核对原文。';
  const success=commitWorkflow(()=>{
    if(result.summary&&!state.sourceSummaries.some(d=>d.sourceId===source&&d.evidence===result.summary.evidence))state.sourceSummaries.unshift({...result.summary,id:crypto.randomUUID(),sourceId:source,source:sourceName(source),category:'本地摘录',why:'来自指定来源的原文摘录。',action:'核对原文后决定下一步。',label:'手动导入 · 规则摘录'});
    if(result.opportunity?.kind==='opportunity'){
      const item={...result.opportunity,id:crypto.randomUUID(),sources:[source],saved:false,applied:false,ignored:false,origin:'manual'},ingested=C.ingest(state.items,item);state.items=ingested.items;id=ingested.item.id;
      if(ingested.item.status==='cancelled')state.reminders=state.reminders.filter(r=>r.itemId!==id);
      title=ingested.kind==='duplicate'?'重复事项已合并':ingested.kind==='updated'?'事项变更已保留':'已提取通知要点';
      detail=C.matches(ingested.item,state.prefs)?'请核对截止时间、参与条件和办理方式，再导出日历或标记处理。':'未符合关注条件，保留在“所选来源全部”供核对。';
    }else if(!result.summary){title='未识别到事项';detail='可补充明确的活动、作业或校园事务通知再试。';}
    state.logs.unshift({time:new Date().toLocaleTimeString('zh-CN'),title,detail});state.logs=state.logs.slice(0,30);
  });
  if(!success)return;render();lastResult=id;target.innerHTML=`<div class="analysis-result"><h3>${esc(title)}</h3><p>${esc(detail)}</p>${id?button('detail','核对与处理','primary small',`data-id="${esc(id)}"`):result.summary?button('navigate','查看摘要','small','data-page="digest"'):''}</div>`;
  if(id&&state.workflow.opportunityMode==='instant'&&C.matches(state.items.find(x=>x.id===id),state.prefs))toast(title);
};
const simulationWorkflow=simulation;
simulation=function(){simulationWorkflow();const input=$('#message-form textarea[name="message"]');if(input)input.placeholder='【线性代数作业】\n提交截止：明天20:00\n面向：大一学生\n提交方式：教学平台上传PDF';const description=$('#modal-content .modal-description');if(description)description.textContent='只处理已选来源。提取活动、作业及校园事务的要点，保留原文供核对；正文不上传。';const hint=$('#message-form .field-hint');if(hint)hint.textContent='支持明确日期和今天 / 明天 / 后天。仅有日期但没有时刻时，需要你核对后才能导出日历。';};
const libraryWorkflow=libraryView;
libraryView=function(){return libraryWorkflow().replace(/<button class="btn primary" data-action="capture">[\s\S]*?<\/button>/,button('quick-save','快速收藏','primary'));};
function quickSave(){showModal(`<h2 id="modal-title">快速收藏</h2><p class="modal-description">直接粘贴平台分享文字或链接，先收下，稍后整理。</p><div class="modal-actions">${button('capture','添加笔记 / 图片','text small')}</div><form id="quick-save-form"><label class="field">分享文字 / 链接<textarea name="shared" maxlength="12000" required placeholder="粘贴小红书、知乎、B站的分享文字或链接…"></textarea></label><label class="field">标题（可留空）<input name="title" maxlength="100" placeholder="留空时使用分享文字或网站名称"></label><label class="field">这次收藏用来做什么？<select name="intent"><option value="later">以后阅读 / 观看</option><option value="reference">留作备查</option></select></label><p class="field-hint">只保存你粘贴的内容，链接不会自动抓取全文或解析视频。</p><p class="form-error" id="quick-error" role="alert"></p><button class="btn primary" type="submit">保存</button></form>`);}
function contentPlan(id){const x=state.brain.items.find(x=>x.id===id);if(!x)return;showModal(`<h2 id="modal-title">这条收藏的下一步</h2><p class="modal-description">${esc(x.title)}</p><form id="content-plan-form" data-id="${esc(id)}"><label class="field">保存意图<select name="intent">${[['later','以后阅读 / 观看'],['reference','留作备查'],['archive','暂时不需要']].map(([v,t])=>`<option value="${v}" ${x.intent===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">准备怎么用？（可选）<input name="purpose" maxlength="200" value="${esc(x.purpose||'')}" placeholder="例如：周末写项目时查 API 用法"></label><label class="field">下次查看日期（可选）<input name="reviewDate" type="date" value="${esc(x.reviewDate||'')}"></label><p class="field-hint">设置日期后会在稍后看页面归入到期内容；不会产生系统推送。</p><button type="submit" class="btn primary">保存安排</button></form>`);}
const contentDetailWorkflow=contentDetail;
contentDetail=function(id){contentDetailWorkflow(id);const x=state.brain.items.find(x=>x.id===id);if(!x||x.deleted)return;$('#modal-content').innerHTML+=`<section class="content-next"><p class="sub">${x.intent==='archive'?'暂时不需要':x.intent==='reference'?'留作备查':'以后阅读 / 观看'}${x.purpose?' · '+esc(x.purpose):''}${x.reviewDate?' · '+esc(x.reviewDate)+' 再看':''}</p><div class="modal-actions">${button('content-plan','安排下一步','small',`data-id="${esc(id)}"`)}${button('content-reviewed','本次已看过','small',`data-id="${esc(id)}"`)}</div></section>`;};
watchView=function(){showTrash=false;const items=state.brain.items.filter(x=>!x.deleted&&x.watch),today=W.day(new Date()),period=state.workflow.reviewMode==='daily'?1:7;
  const due=items.filter(x=>x.reviewDate?x.reviewDate<=today:state.workflow.reviewMode==='open'||Date.now()-Date.parse(x.lastReviewed||x.createdAt)>=period*86400000);
  return header('','','',button('quick-save','快速收藏','primary'))+`<p class="feed-note">${items.length} 条待看 · ${due.length} 条到期回顾 · 不必把每条收藏都看完。</p><div class="review-controls">${button('review-now','现在回顾 3 条','small')}${button('all-collections','返回资料库','text small')}</div>${items.map(x=>`<article class="review-item"><button class="content-title" data-action="content-detail" data-id="${esc(x.id)}">${esc(x.title)}</button><p class="sub">${esc(x.purpose||x.summary)}${x.reviewDate?' · '+esc(x.reviewDate)+' 再看':''}</p><div class="modal-actions">${button('content-reviewed','本次已看过','small',`data-id="${esc(x.id)}"`)}${button('content-plan','安排 / 备查','small',`data-id="${esc(x.id)}"`)}</div></article>`).join('')||'<div class="empty"><h3>没有待看内容</h3><p>备查内容不需要加入回看清单。</p></div>'}`;
};
const renderWorkflow=render;
render=function(){ensureWorkflow();renderWorkflow();};
remindersModal=function(){showModal(`<h2 id="modal-title">提醒方式</h2><p class="modal-description">通知事项：${{daily:'每天汇总',instant:'导入时即时提示',open:'仅打开时查看'}[state.workflow.opportunityMode]}。<br>稍后看：${{weekly:'每周回顾',daily:'每天回顾',open:'仅打开时查看'}[state.workflow.reviewMode]}。</p><p class="field-hint">目前没有后台推送。需要实际截止提醒，请打开事项、核对时间后导出 .ics，再导入系统日历。</p>${button('navigate','管理提醒偏好','primary','data-page="settings"')}`);};
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id,value}=b.dataset;
  if(action==='task-scope'){taskScope=value;render();}
  if(action==='edit-task')editTask(id);
  if(action==='complete-task'){const x=state.items.find(x=>x.id===id);if(x&&commitWorkflow(()=>{x.applied=!x.applied;if(x.applied)state.reminders=state.reminders.filter(r=>r.itemId!==id);})){render();showDetail(id);toast(x.applied?'已标记处理，不会实际提交':'已撤销处理标记');}}
  if(action==='calendar-task'){const x=state.items.find(x=>x.id===id);if(x){try{const content=W.calendar(x);showModal(`<h2 id="modal-title">导出截止提醒</h2><p class="modal-description">${esc(x.title)}<br>${esc(dateText(x.deadline))} 截止 · 北京时间<br>提前 1 小时提醒。请先确认原文，导入日历后才会生效。</p><p class="field-hint">文件包含这条事项的原文、标题和地点，供你核对。只有你选定的日历会接收这些内容。</p>${button('confirm-calendar','下载 .ics 文件','primary',`data-id="${esc(id)}"`)}`);}catch(err){toast(err.message);}}}
  if(action==='confirm-calendar'){const x=state.items.find(x=>x.id===id);try{download('Sift-截止提醒.ics',W.calendar(x),'text/calendar');toast('请在系统日历确认导入并检查提醒');}catch(err){toast(err.message);}}
  if(action==='quick-save')quickSave();
  if(action==='content-plan')contentPlan(id);
  if(action==='content-reviewed'){const x=state.brain.items.find(x=>x.id===id);if(x&&commitWorkflow(()=>{x.lastReviewed=new Date().toISOString();x.reviewDate='';})){closeModal();render();toast('已记录本次回顾，不代表已读完');}}
  if(action==='review-now'){const today=W.day(new Date());const items=state.brain.items.filter(x=>x.watch&&!x.deleted).sort((a,b)=>(a.reviewDate||'9999').localeCompare(b.reviewDate||'9999')||Date.parse(a.lastReviewed||a.createdAt)-Date.parse(b.lastReviewed||b.createdAt)).slice(0,3);showModal(`<h2 id="modal-title">这次只看 3 条</h2><p class="modal-description">先决定要不要继续读。也可以留作备查，或暂时归档。</p>${items.map(x=>`<article class="review-item"><button class="content-title" data-action="content-detail" data-id="${esc(x.id)}">${esc(x.title)}</button><p class="sub">${esc(x.summary)}</p>${button('content-plan','决定下一步','small',`data-id="${esc(x.id)}"`)}</article>`).join('')||'<p>当前没有待看内容。</p>'}`);}
});
document.addEventListener('change',e=>{if(e.target.id==='task-state'){taskState=e.target.value;render();}});
document.addEventListener('submit',e=>{
  const form=e.target,fd=new FormData(form);
  if(form.id==='workflow-prefs'){e.preventDefault();if(commitWorkflow(()=>{state.workflow={include:String(fd.get('include')||'').trim(),exclude:String(fd.get('exclude')||'').trim(),grade:String(fd.get('grade')||''),opportunityMode:fd.get('opportunityMode'),reviewMode:fd.get('reviewMode'),digestTime:fd.get('digestTime')};state.prefs.types=fd.getAll('types');state.prefs.instant=state.workflow.opportunityMode==='instant';})){render();toast('关注与提醒偏好已保存');}}
  if(form.id==='task-form'){e.preventDefault();const x=state.items.find(x=>x.id===form.dataset.id),v=String(fd.get('deadline')||''),d=W.dateValue(v);if(v&&(!d.iso||d.error)){$('#task-error').textContent='请填写有效的截止日期与时间';return;}if(x&&commitWorkflow(()=>{for(const key of ['title','eventTime','location','eligibility','actionText'])x[key]=String(fd.get(key)||'').trim();x.type=fd.get('type');x.deadline=d.iso;x.deadlineDay=d.date||x.deadlineDay||null;x.verifiedAt=new Date().toISOString();})){render();showDetail(x.id);toast('核对结果已保存');}}
  if(form.id==='quick-save-form'){e.preventDefault();const shared=String(fd.get('shared')||'').trim(),match=shared.match(/https?:\/\/[^\s<>"'，。；]+/),url=match?B.cleanUrl(match[0].replace(/[)）\]】]+$/,'')):null;const suggested=shared.replace(match?.[0]||'','').trim().split('\n')[0].slice(0,100);const parsed=B.validate({title:String(fd.get('title')||'').trim()||suggested||(url?B.platform(url)+'链接':'收藏笔记'),url:url||'',text:shared===match?.[0]?'':shared,category:'auto',tags:''});if(parsed.error){$('#quick-error').textContent=parsed.error;return;}if(url&&state.brain.items.some(x=>!x.deleted&&x.url===url)){$('#quick-error').textContent='这个链接已收藏，可在资料库搜索后编辑。';return;}const intent=fd.get('intent');if(commitWorkflow(()=>state.brain.items.unshift({...parsed.value,id:crypto.randomUUID(),intent,watch:intent==='later',collections:[],createdAt:new Date().toISOString(),deleted:false,saved:true}))){closeModal();page='library';render();toast('已保存分享内容，未抓取链接正文');}}
  if(form.id==='content-plan-form'){e.preventDefault();const x=state.brain.items.find(x=>x.id===form.dataset.id),intent=fd.get('intent');if(x&&commitWorkflow(()=>{x.intent=intent;x.watch=intent==='later';x.purpose=String(fd.get('purpose')||'').trim();x.reviewDate=String(fd.get('reviewDate')||'');})){closeModal();render();toast(intent==='reference'?'已留作备查，不加入回看清单':intent==='archive'?'已移出回看清单，资料库中仍可找到':'回看安排已保存');}}
});
persist();render();
